  Future<String> getLanguage() async {
    final prefs = await SharedPreferences.getInstance();
    return prefs.getString(_languageKey) ?? 'sw';
  }

  Future<void> setLanguage(String code) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString(_languageKey, code);
  }

  Future<String> getCurrency() async {
    final prefs = await SharedPreferences.getInstance();
    return prefs.getString(_currencyKey) ?? 'TZS';
  }

  Future<void> setCurrency(String code) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString(_currencyKey, code);
  }

  String getCurrencySymbol(String code) {
    return supportedCurrencies[code]?['symbol'] ?? 'TSh';
  }

  static String translate(String key, String languageCode) {
    final localized = translations[languageCode]?[key];
    if (localized != null && localized.isNotEmpty) return localized;
    final english = translations['en']?[key];
    if (english != null && english.isNotEmpty) return english;
    return humanizeKey(key);
  }

  static String trParams(String key, String languageCode, Map<String, String> params) {
    String text = translate(key, languageCode);
    for (final entry in params.entries) {
      text = text.replaceAll('{${entry.key}}', entry.value);
    }
    return text;
  }

  /// Turns `forgot_password` into "Forgot Password" if a key is missing.
  static String humanizeKey(String key) {
    return key
        .split('_')
        .where((part) => part.isNotEmpty)
        .map(
          (part) => part.length == 1
              ? part.toUpperCase()
              : '${part[0].toUpperCase()}${part.substring(1)}',
        )
        .join(' ');
  }
}
